let mats =
"""
SHADER metaballs
    VERTEX
        INPUTS apos:4 atc:2
        UNIFORMS mvp
        gl_Position = mvp * apos;
        itc = atc;
    PIXEL
        INPUTS itc:2
        UNIFORM float time
        vec2 uv = itc * 2.0 - 1.0;
        float v = 0.0;
        for (int i = 0; i < 100; i++) {
            vec2 c = sin(time * (0.1 + float(i) / 300.0) + vec2(i, -i));
            v += 1.0 - smoothstep(0.0, 0.2, length(uv - c));
        }
        frag_color = vec4(mix(vec3(v), vec3(1.0), smoothstep(0.9, 0.9, v)), 1.0);
"""

